	// Compute per-scorer scores separately for adaptive weighting
	rawScores := make([]map[string]float64, len(ws.scorers))
	for i, scorer := range ws.scorers {
		dimScores := scorer(req, snapshots)
		rawScores[i] = make(map[string]float64, len(snapshots))
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			if s < 0 {
				s = 0
			}
			if s > 1 {
				s = 1
			}
			rawScores[i][snap.ID] = s
		}
	}

	// Adaptive weight calculation
	// Baseline: [prefix-affinity=0.5, load-balance=0.5]
	adaptiveWeights := make([]float64, len(ws.weights))
	copy(adaptiveWeights, ws.weights)

	if len(adaptiveWeights) >= 2 {
		// Adjust based on input length
		if inputLen < 100 {
			// Short inputs: strongly favor load-balance (minimal cache benefit)
			adaptiveWeights[0] = 0.2  // prefix-affinity
			adaptiveWeights[1] = 0.8  // load-balance
		} else if inputLen < 200 {
			// Medium inputs: moderate favor to load-balance
			adaptiveWeights[0] = 0.35
			adaptiveWeights[1] = 0.65
		} else {
			// Long inputs: favor prefix-affinity (substantial cache benefit)
			adaptiveWeights[0] = 0.65
			adaptiveWeights[1] = 0.35
		}

		// SLO class adjustment
		if req.SLOClass == "realtime" {
			// Realtime is latency-sensitive: boost load-balance
			adaptiveWeights[0] *= 0.6
			adaptiveWeights[1] *= 1.4
		} else if req.SLOClass == "batch" {
			// Batch can tolerate queuing: slightly favor cache
			adaptiveWeights[0] *= 1.2
			adaptiveWeights[1] *= 0.8
		}

		// Multi-turn session with substantial prefix: strongly favor cache affinity
		if req.SessionID != "" && inputLen >= 150 {
			adaptiveWeights[0] *= 1.5
			adaptiveWeights[1] *= 0.7
		}

		// Normalize weights
		total := adaptiveWeights[0] + adaptiveWeights[1]
		if total > 0 {
			adaptiveWeights[0] /= total
			adaptiveWeights[1] /= total
		}
	}

